import React, { useState, useEffect } from 'react';
import axios from 'axios';

export default function ManageSubjects() {
  const [subjects, setSubjects] = useState([]);
  const [subjectCode, setSubjectCode] = useState(''); 
  const [subjectName, setSubjectName] = useState('');

  const fetchSubjects = () => {
    axios.get('http://localhost:8081/api/view-subjects')
      .then(res => setSubjects(res.data))
      .catch(err => console.error("Error fetching subjects:", err));
  };

  useEffect(() => { fetchSubjects(); }, []);

  const handleSubmit = (e) => {
    e.preventDefault();
    axios.post('http://localhost:8081/api/add-subject', { 
      subject_code: subjectCode, 
      subject_name: subjectName 
    })
      .then((res) => {
        if (res.data.status === "Error") {
          alert("Database Error: " + res.data.error);
        } else {
          fetchSubjects();
          setSubjectCode(''); 
          setSubjectName(''); 
        }
      })
      .catch(err => alert("Error adding subject!"));
  };

  const handleDelete = (id) => {
    if (window.confirm("Are you sure you want to delete this subject?")) {
      axios.delete(`http://localhost:8081/api/delete-subject/${id}`)
        .then(() => fetchSubjects());
    }
  };

  const handleEdit = (subject) => {
    // Database එකේ නම් වලට හරියටම ගැලපෙන්න හැදුවා
    const currentId = subject.Id; 
    const currentCode = subject.Subject_Code;
    const currentName = subject.subject_name;

    if (!currentCode) {
        alert("Cannot edit! Subject Code is missing.");
        return;
    }

    const newCode = window.prompt("Enter new Subject Code:", currentCode);
    const newName = window.prompt("Enter new Subject Name:", currentName);

    if (newCode && newName) {
      axios.put(`http://localhost:8081/api/edit-subject/${currentCode}`, {
        subject_code: newCode,
        subject_name: newName
      }).then(() => fetchSubjects())
        .catch(err => alert("Error updating subject!"));
    }
  };

  return (
    <div style={{ padding: '30px', fontFamily: 'sans-serif', backgroundColor: '#fff', borderRadius: '15px', boxShadow: '0 4px 15px rgba(0,0,0,0.05)' }}>
      <h2 style={{ color: '#15803d', marginBottom: '25px' }}>📚 Manage Subjects</h2>
      
      <form onSubmit={handleSubmit} style={{ marginBottom: '30px', display: 'flex', gap: '15px' }}>
        <input 
          type="text" 
          placeholder="Subject Code (e.g. 001)" 
          value={subjectCode} 
          onChange={(e) => setSubjectCode(e.target.value)} 
          required 
          style={{ padding: '12px', width: '200px', borderRadius: '8px', border: '1px solid #cbd5e1', outline: 'none' }}
        />
        <input 
          type="text" 
          placeholder="Enter new subject name..." 
          value={subjectName} 
          onChange={(e) => setSubjectName(e.target.value)} 
          required 
          style={{ padding: '12px', width: '350px', borderRadius: '8px', border: '1px solid #cbd5e1', outline: 'none' }}
        />
        <button type="submit" style={{ padding: '10px 25px', backgroundColor: '#15803d', color: 'white', border: 'none', borderRadius: '8px', cursor: 'pointer', fontWeight: 'bold' }}>+ Add Subject</button>
      </form>

      <table style={{ width: '100%', borderCollapse: 'collapse' }}>
        <thead>
          <tr style={{ backgroundColor: '#f8fafc', textAlign: 'left' }}>
            <th style={{ padding: '15px', borderBottom: '2px solid #e2e8f0', color: '#64748b' }}>ID</th>
            <th style={{ padding: '15px', borderBottom: '2px solid #e2e8f0', color: '#64748b' }}>Subject Code</th>
            <th style={{ padding: '15px', borderBottom: '2px solid #e2e8f0', color: '#64748b' }}>Subject Name</th>
            <th style={{ padding: '15px', borderBottom: '2px solid #e2e8f0', color: '#64748b', textAlign: 'center' }}>Actions</th>
          </tr>
        </thead>
        <tbody>
          {subjects.map(s => {
            // මෙතනත් Database එකේ තියෙන විදියටම කැපිටල් අකුරු දුන්නා
            const itemId = s.Id; 
            const itemCode = s.Subject_Code; 
            const itemName = s.subject_name;

            return (
            <tr key={itemId || Math.random()} style={{ borderBottom: '1px solid #f1f5f9' }}>
              <td style={{ padding: '15px', fontWeight: 'bold', color: '#475569' }}>{itemId || '-'}</td>
              <td style={{ padding: '15px', fontWeight: 'bold', color: '#0369a1' }}>{itemCode || '-'}</td>
              <td style={{ padding: '15px', fontSize: '16px', color: '#1e293b' }}>{itemName}</td>
              <td style={{ padding: '15px', textAlign: 'center' }}>
                <button onClick={() => handleEdit(s)} style={{ padding: '6px 12px', backgroundColor: '#e0f2fe', color: '#0284c7', border: 'none', borderRadius: '6px', cursor: 'pointer', marginRight: '10px' }}>Edit</button>
                <button onClick={() => handleDelete(itemCode)} style={{ padding: '6px 12px', backgroundColor: '#fee2e2', color: '#dc2626', border: 'none', borderRadius: '6px', cursor: 'pointer' }}>Delete</button>
              </td>
            </tr>
            );
          })}
        </tbody>
      </table>
    </div>
  );
}
